import sys
import math

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out = []

    for case in range(t):
        m = int(data[idx]); n = int(data[idx+1]); idx += 2

        if m < 2:
            m = 2

        if m <= n:
            limit = int(math.isqrt(n)) + 1
            # simple sieve for primes up to sqrt(n)
            sieve = bytearray(b'\x01') * (limit + 1)
            sieve[0:2] = b'\x00\x00'
            for i in range(2, int(math.isqrt(limit)) + 1):
                if sieve[i]:
                    start = i * i
                    sieve[start:limit+1:i] = b'\x00' * (((limit - start) // i) + 1)
            primes = [i for i in range(2, limit + 1) if sieve[i]]

            size = n - m + 1
            segment = bytearray(b'\x01') * size

            for p in primes:
                start = max(p * p, ((m + p - 1) // p) * p)
                if start > n:
                    continue
                segment[start - m:n - m + 1:p] = b'\x00' * (((n - start) // p) + 1)

            for i in range(size):
                if segment[i]:
                    out.append(str(m + i))

        if case != t - 1:
            out.append("")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
